import { test, expect } from '@playwright/test';

test.describe('Countdown Timer Interval Update', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/timer');
  });

  test('should update countdown timer every second using interval', async ({ page }) => {
    // Verify initial countdown value
    const countdownDisplay = page.getByRole('heading', { name: /countdown/i });
    await expect(countdownDisplay).toBeVisible();
    const initialCountdownValue = page.getByText(/10 seconds/i);
    await expect(initialCountdownValue).toBeVisible();

    // Verify interval is set up
    const intervalElement = page.getByRole('heading', { name: /interval/i });
    await expect(intervalElement).toBeVisible();

    // Verify timer starts
    const startButton = page.getByRole('button', { name: /start/i });
    await expect(startButton).toBeVisible();
    await startButton.click();

    // Wait for interval to trigger first update
    await page.waitForTimeout(1000);

    // Verify countdown value has decreased
    const updatedCountdownValue = page.getByText(/9 seconds/i);
    await expect(updatedCountdownValue).toBeVisible();

    // Verify interval is still active
    await expect(intervalElement).toBeVisible();

    // Wait for another second
    await page.waitForTimeout(1000);

    // Verify countdown value has decreased again
    const updatedCountdownValue2 = page.getByText(/8 seconds/i);
    await expect(updatedCountdownValue2).toBeVisible();

    // Verify interval is still active
    await expect(intervalElement).toBeVisible();

    // Wait for final second
    await page.waitForTimeout(1000);

    // Verify countdown reaches 0
    const finalCountdownValue = page.getByText(/0 seconds/i);
    await expect(finalCountdownValue).toBeVisible();

    // Verify interval is still active
    await expect(intervalElement).toBeVisible();

    // Verify timer has stopped
    const stopButton = page.getByRole('button', { name: /stop/i });
    await expect(stopButton).toBeVisible();

    // Verify countdown display is empty
    const emptyCountdownDisplay = page.getByRole('heading', { name: /countdown/i });
    await expect(emptyCountdownDisplay).toBeVisible();

    // Verify countdown value is empty
    const emptyCountdownValue = page.getByText(/0 seconds/i);
    await expect(emptyCountdownValue).not.toBeVisible();

    // Verify stop button is visible
    await expect(stopButton).toBeVisible();
  });

  test('should handle interval reset and continue countdown', async ({ page }) => {
    // Verify initial countdown value
    const countdownDisplay = page.getByRole('heading', { name: /countdown/i });
    await expect(countdownDisplay).toBeVisible();
    const initialCountdownValue = page.getByText(/10 seconds/i);
    await expect(initialCountdownValue).toBeVisible();

    // Verify interval is set up
    const intervalElement = page.getByRole('heading', { name: /interval/i });
    await expect(intervalElement).toBeVisible();

    // Verify timer starts
    const startButton = page.getByRole('button', { name: /start/i });
    await expect(startButton).toBeVisible();
    await startButton.click();

    // Wait for interval to trigger first update
    await page.waitForTimeout(1000);

    // Verify countdown value has decreased
    const updatedCountdownValue = page.getByText(/9 seconds/i);
    await expect(updatedCountdownValue).toBeVisible();

    // Verify interval is still active
    await expect(intervalElement).toBeVisible();

    // Wait for another second
    await page.waitForTimeout(1000);

    // Verify countdown value has decreased again
    const updatedCountdownValue2 = page.getByText(/8 seconds/i);
    await expect(updatedCountdownValue2).toBeVisible();

    // Verify interval is still active
    await expect(intervalElement).toBeVisible();

    // Wait for final second
    await page.waitForTimeout(1000);

    // Verify countdown reaches 0
    const finalCountdownValue = page.getByText(/0 seconds/i);
    await expect(finalCountdownValue).toBeVisible();

    // Verify interval is still active
    await expect(intervalElement).toBeVisible();

    // Verify timer has stopped
    const stopButton = page.getByRole('button', { name: /stop/i });
    await expect(stopButton).toBeVisible();

    // Verify countdown display is empty
    const emptyCountdownDisplay = page.getByRole('heading', { name: /countdown/i });
    await expect(emptyCountdownDisplay).toBeVisible();

    // Verify countdown value is empty
    const emptyCountdownValue = page.getByText(/0 seconds/i);
    await expect(emptyCountdownValue).not.toBeVisible();

    // Verify stop button is visible
    await expect(stopButton).toBeVisible();

    // Verify interval is still active
    await expect(intervalElement).toBeVisible();

    // Verify reset button is visible
    const resetButton = page.getByRole('button', { name: /reset/i });
    await expect(resetButton).toBeVisible();

    // Verify countdown starts again after reset
    await resetButton.click();

    // Wait for interval to trigger first update
    await page.waitForTimeout(1000);

    // Verify countdown value has decreased
    const updatedCountdownValue3 = page.getByText(/9 seconds/i);
    await expect(updatedCountdownValue3).toBeVisible();

    // Verify interval is still active
    await expect(intervalElement).toBeVisible();
  });
});
